// post.js — appended via emcc --extern-post-js, so it runs ONCE at top level
// after the initAvoidModule factory is defined. Makes the bundle self-contained
// and self-publishing (like drawio-mermaid's mxMermaidToDrawio): draw.io loads
// this one file and gets a ready `window.Avoid`, with no separate loader.
//
// The module is pure JS built with -sWASM_ASYNC_COMPILATION=0, so
// initAvoidModule(mod) populates the embind classes on `mod` SYNCHRONOUSLY
// before it returns — we publish window.Avoid in one tick, no promise to await.
// window.__libavoidReady is kept as an already-resolved promise for back-compat
// with callers that still await it.
(function () {
    if (typeof initAvoidModule === 'undefined' || initAvoidModule == null) {
        return;
    }

    try {
        var mod = {};

        // libavoid's stderr: the solver prints "Warning: skipping checkpoint for
        // connector ..." when it discards a jetty checkpoint it cannot honour
        // (e.g. a drag momentarily buries a pinned anchor) — non-actionable, so
        // demote to console.debug; anything else keeps the console.error default.
        mod.printErr = function (msg) {
            if (typeof console === 'undefined') { return; }
            if (/^Warning: skipping checkpoint\b/.test(msg)) {
                if (console.debug != null) { console.debug('[libavoid]', msg); }
            } else {
                console.error(msg);
            }
        };

        // Synchronous — embind classes are on `mod` before this returns.
        initAvoidModule(mod);

        globalThis.Avoid = mod;
        globalThis.__libavoidReady = Promise.resolve(mod);
    } catch (e) {
        if (typeof console !== 'undefined') {
            console.error('[libavoid] init failed; routing disabled:', (e && e.message), e);
        }
        globalThis.__libavoidReady = Promise.resolve(null);
    }
})();
